  "deed.quran-listening.exp": "﴿فَاسْتَمِعُوا لَهُ وَأَنصِتُوا لَعَلَّكُمْ تُرْحَمُونَ﴾",
  "deed.quran-listening.label": "الاستماع إلى تلاوة القرآن",
  "deed.quran-memorization.exp": "«خيركم من تعلّم القرآن وعلّمه»",
  "deed.quran-memorization.label": "حفظ آية (آيات) جديدة",
  "deed.quran-recitation.exp": "رمضان شهر القرآن — اقرأ صفحاتك اليومية.",
  "deed.quran-recitation.label": "تلاوة القرآن (الورد اليومي)",
  "deed.quran-reflection.exp": "التأمل العميق يغيّر القلب ويوجّه العمل.",
  "deed.quran-reflection.label": "تدبر المعاني",
  "deed.renew-tomorrow.exp": "«أحب الأعمال أدومها إلى الله»",
  "deed.renew-tomorrow.label": "تجديد النية للغد",
